parameters.jsCode:
// Convierte cada evento del outbox en un aviso (solo ventas y consultas).
const out = [];
for (const item of $input.all()) {
  const e = item.json;
  const p = e.payload || {};
  if (e.event_type === 'order.created') {
    out.push({ json: {
      id: e.id,
      asunto: `🛒 Nueva venta — Pedido ${String(e.aggregate_id).slice(0, 8)}`,
      cuerpo: `Se registró una venta en la tienda.\n\nCliente: ${p.cliente_nombre || '-'}\nEmail: ${p.cliente_email || '-'}\nTeléfono: ${p.cliente_telefono || '-'}\nTotal: $${p.total || '-'}\nCanal: ${p.channel || 'web'}\n\nRevisá el pedido en el panel.`
    }});
  } else if (e.event_type === 'consulta.created') {
    out.push({ json: {
      id: e.id,
      asunto: `💡 Nueva consulta de asesoramiento — ${p.nombre || ''}`,
      cuerpo: `Nuevo pedido de asesoramiento / proyecto.\n\nNombre: ${p.nombre || '-'}\nContacto: ${[p.email, p.telefono].filter(Boolean).join(' · ') || '-'}\nTipo de proyecto: ${p.tipo_proyecto || '-'}\nMensaje: ${p.mensaje || '-'}`
    }});
  }
}
return out;

